import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    root = {}
    for i in range(1, n + 1):
        node = root
        for ch in data[i]:
            nxt = node.get(ch)
            if nxt is None:
                nxt = {}
                node[ch] = nxt
            node = nxt
        node['$'] = True
    q = int(data[n + 1])
    out = []
    for i in range(n + 2, n + 2 + q):
        s = data[i]
        node = root
        best = 0
        for j, ch in enumerate(s):
            node = node.get(ch)
            if node is None:
                break
            if '$' in node:
                best = j + 1
        out.append(s[:best] if best else 'NONE')
    print('\n'.join(out))

