import java.util.*;
import java.io.*;

public class Main {
    static String[] longestPrefixMatch(String[] prefixes, String[] queries) {
        // For each query return the longest prefix that the query starts with, or "NONE"
        // Write your solution here
        String[] res = new String[queries.length];
        Arrays.fill(res, "NONE");
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        String[] prefixes = new String[n];
        for (int i = 0; i < n; i++) prefixes[i] = st.nextToken();
        int q = Integer.parseInt(st.nextToken());
        String[] queries = new String[q];
        for (int i = 0; i < q; i++) queries[i] = st.nextToken();
        StringBuilder sb = new StringBuilder();
        for (String s : longestPrefixMatch(prefixes, queries)) sb.append(s).append("\n");
        System.out.print(sb);
    }
}
